import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as sla, statistics
n=300; density=0.01; k=5

def validate(ncv, seeds=200):
    failures=0
    for seed in range(seeds):
        rng=np.random.default_rng(seed)
        A=sp.random(n,n,density=density,format='csr',data_rvs=rng.standard_normal)
        v0=np.ones(n)
        # reference with ncv=20
        vals_exp,vecs_exp=sla.eigs(A,k=k,v0=v0,ncv=20,maxiter=n*200)
        exp=[p[1] for p in sorted(zip(vals_exp,vecs_exp.T),key=lambda p:-abs(p[0]))]
        try:
            vals,vecs=sla.eigs(A,k=k,v0=v0,ncv=ncv,maxiter=n*200)
        except Exception:
            failures+=1
            continue
        sol=[p[1] for p in sorted(zip(vals,vecs.T),key=lambda p:-abs(p[0]))]
        ok=True
        for e,s in zip(exp,sol):
            if np.abs(np.dot(np.conj(e),s))/ (np.linalg.norm(e)*np.linalg.norm(s)) < 1-1e-6:
                ok=False
                break
        if not ok:
            failures+=1
    return failures
for ncv in [13,15,17,19,20]:
    fail=validate(ncv)
    print('ncv',ncv,'fail',fail)
